-- O termo de autorização do colégio passa a ser UM só: "Termo de autorização para uso de imagem em campanhas de mídia paga (tráfego pago)".
-- Os modelos de exemplo criados antes ficam inativos (nada é apagado). O termo pede o CPF do responsável: só o necessário e só para quem autoriza.
ALTER TABLE ui_solicitacoes
  ADD COLUMN resp_cpf VARCHAR(14) NOT NULL DEFAULT '',
  ADD COLUMN pede_cpf TINYINT NOT NULL DEFAULT 0;
UPDATE ui_modelos SET ativo=0 WHERE nome IN ('Modelo padrão - atividades escolares','Modelo tráfego pago (anúncios)');
INSERT IGNORE INTO ui_modelos(nome,tipo,finalidade,canais,local_uso,periodo_tipo,periodo_valor,observacoes,corpo,versao,ativo,criado_em,atualizado_em,atualizado_por) VALUES(
 'Termo de autorização - mídia paga (tráfego pago)','PADRAO',
 'Uso da imagem do(a) aluno(a) em campanhas de mídia paga e tráfego pago (Meta Ads, Google Ads, TikTok Ads e ferramentas correlatas), para fins exclusivos de divulgação institucional e captação de matrículas.',
 'Tráfego pago (anúncios)',
 'Campanhas de mídia paga do Colégio Evolução','INDETERMINADO','',
 '',
 '# TERMO DE AUTORIZAÇÃO PARA USO DE IMAGEM EM CAMPANHAS DE MÍDIA PAGA (TRÁFEGO PAGO)\n\n## Identificação\nNome do(a) aluno(a): {{aluno}}\nTurma / Ano letivo: {{turma}} / {{ano}}\nNome do(a) responsável legal: {{responsavel}}\nCPF do(a) responsável legal: {{cpf}}\n\n## Finalidade\nO Colégio Evolução solicita autorização para utilizar a imagem do(a) aluno(a) acima identificado(a) em campanhas de mídia paga e tráfego pago — impulsionamento de conteúdo em plataformas digitais de anúncios, incluindo, mas não se limitando a, Meta Ads (Facebook/Instagram), Google Ads, TikTok Ads e ferramentas correlatas —, para fins exclusivos de divulgação institucional e captação de matrículas.\n\n## Condições de uso\na) não são realizadas, pelo Colégio Evolução ou por terceiros, técnicas de perfilamento comportamental, análise emocional ou qualquer forma de segmentação publicitária direcionada à criança ou ao adolescente a partir de sua imagem ou de seus dados pessoais, em conformidade com o art. 22 da Lei nº 15.211/2025 (ECA Digital);\n\nb) a imagem poderá ser processada por plataformas de terceiros exclusivamente para fins de veiculação, entrega e mensuração do anúncio, sendo o público-alvo da campanha os responsáveis legais e o público em geral interessado em informações sobre a Escola, e não a criança ou o adolescente;\n\nc) esta autorização poderá ser revogada a qualquer tempo, mediante simples comunicação por escrito à Secretaria da Escola (presencialmente ou por e-mail/formulário próprio disponibilizado para esse fim), cessando-se o uso da imagem nas campanhas em curso em prazo razoável, observadas as limitações técnicas de cada plataforma.\n\n## Manifestação de vontade\n[   ] AUTORIZO o uso da imagem do(a) aluno(a) acima identificado(a) em campanhas de mídia paga (tráfego pago), nos termos e condições descritos neste Termo.\n\nA ausência de manifestação, ou a manifestação de não autorização, não implicará qualquer prejuízo pedagógico, disciplinar ou contratual ao(à) aluno(a).\n\nEste Termo tem fundamento na Lei nº 8.069/1990 (Estatuto da Criança e do Adolescente), na Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais), na Lei nº 15.211/2025 (ECA Digital) e no art. 5º, inciso X, da Constituição Federal de 1988.\n\nJoão Pessoa, {{data}}.',
 1,1,'2026-10-29T00:00:00-03:00','2026-10-29T00:00:00-03:00','Sistema');
